local root=assert(os.getenv('QCOM_VP_PROBE_ROOT'))..'/'
platform={moduletype='Container',qemu_inst_mgr={moduletype='QemuInstanceManager'},
    apss_instance={moduletype='QemuInstance',args={'&qemu_inst_mgr','AARCH64'},accel='tcg',
        sync_policy='multithread-quantum',qemu_args='-d in_asm -D '..root..'producer.log'},
    apss_router={moduletype='router'},
    apss_access={moduletype='AccessMonitor',initiator_socket={bind='&abi.target_socket'}},
    apss={moduletype='cpu_arm_cortexA53',args={'&apss_instance'},rvbar=0x300000,
        has_el3=true,has_el2=true,mem={bind='&apss_access.target_socket'}},
    abi={moduletype='qcom,tme-runtime-abi-bridge-v1',legacy_base=0x416800,
        runtime_base=0x489000,enable_address=0x4a0000,mapping_path=root..'slots.map',
        legacy_channels=0x448f1c,runtime_channels=0x464200,
        initiator_socket={bind='&protection_port.target_socket'}},
    protection_port={moduletype='qcom,tme-protection-port-v1',
        args={'&protection','&apss'},qad=1,runtime_qad=2,
        runtime_phase={bind='&abi.runtime_active'},
        initiator_socket={bind='&apss_router.target_socket'}},
    protection={moduletype='qcom,sm8850-tme-protection',
        region_count=2,address_bits=32,alignment_bits=12,
        target_socket={address=0x500000,size=0x2000,bind='&apss_router.initiator_socket'}},
    rom={moduletype='gs_memory',read_only=true,
        target_socket={address=0x300000,size=0x1000,bind='&apss_router.initiator_socket'},
        load={{bin_file=root..'producer.bin',offset=0}}},
    ram={moduletype='gs_memory',init_mem=true,
        target_socket={address=0x400000,size=0xa1000,bind='&apss_router.initiator_socket'}}}
